"""Anchor-and-Frame: the behavioural school (anchoring, framed concessions, shrinking steps, neutral tone).
Opens with an ambitious, non-round, reasoned anchor; every later concession is presented as costly, is
smaller than the one before and is paired with an ask (longer payment days). Polite, no threats, no bluff.

Knobs: opening_depth (first cut below the quote), first_step (share of the gap conceded first), shrink
(each step as a share of the previous one), min_rounds (our own offers before accepting a non-final sheet).
"""

import math

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..play import closing_move, latest, live_threads, moves_left, standing
from .rational import _first_terms, _message

WALK = {"action": {"type": "walk_away"}}


def _non_round(price, ceiling):
    """A price in cents that does not end in .00 or .50 (nudged down a cent or two), never above ceiling."""
    price = round(min(price, ceiling), 2)
    while round(price * 100) % 50 == 0:
        price = round(price - 0.01, 2)
    return price


class AnchorAgent:
    def __init__(self, opening_depth=0.12, first_step=0.3, shrink=0.6, min_rounds=2):
        self.opening_depth, self.first_step, self.shrink, self.min_rounds = opening_depth, first_step, shrink, min_rounds
        self.case_id, self.state = None, {}  # state: supplier -> {"step": our last step, "price": our last price}

    def decide(self, case, threads):
        try:
            return self._decide(case, threads)
        except Exception:  # never crash a case: close safely (must-haves + alternative), else walk away
            try:
                return closing_move(case, threads)
            except Exception:
                live = live_threads(threads) or list(threads)
                return {"supplier_id": live[0] if live else None, "message": WALK}

    def _decide(self, case, threads):
        if case["case_id"] != self.case_id:
            self.case_id, self.state = case["case_id"], {}
        live = live_threads(threads)
        if not live:
            return {"supplier_id": next(iter(threads), None), "message": WALK}
        std = {s: standard_terms(threads[s]) for s in live}
        cost = lambda s, t: total_cost(case, t, std[s])  # noqa: E731
        quoting = [s for s in live if standing(threads[s])[1].get("unit_price") is not None]
        if not quoting:
            return {"supplier_id": live[0], "message": WALK}
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        has_alt = bool(alt.get("unit_price"))
        opening = [cost(s, _first_terms(threads[s])) for s in quoting if _first_terms(threads[s]).get("unit_price")]
        reservation = total_cost(case, alt) if has_alt else min(opening, default=math.inf)
        sid = min(quoting, key=lambda s: cost(s, standing(threads[s])[1]))
        events = threads[sid]
        sheet_id, terms = standing(events)
        compliant = must_haves_ok(case, terms, std[sid])
        beats = compliant and cost(sid, terms) < reservation
        accept = {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
        status, left = latest(events).get("status"), moves_left(case, events)
        final_ok = beats or (compliant and not has_alt)  # no alternative: walking away scores 0
        sent = sum(m.get("from") == "buyer" for m in events)
        st = self.state.get(sid)
        if not sent or st is None:  # first move here (or a replayed case): start clean
            st = self.state[sid] = {"step": None, "price": None}
        theirs = terms["unit_price"]

        ask = {}
        if "payment_days" in case["negotiable"] and "payment_days" in terms:
            options = case.get("term_options", {}).get("payment_days")
            ask["payment_days"] = max(options) if options else terms["payment_days"] + 30
        if st["price"] is None:
            price, step = _non_round(theirs * (1 - self.opening_depth), theirs), None
            body = "Our cost review of this part and recent market conditions point to this level."
        else:
            step = (self.first_step * (theirs - st["price"])) if st["step"] is None else st["step"] * self.shrink
            price, step = _non_round(st["price"] + step, theirs), step
            body = ("This is a significant move for us, made because we want to reach an agreement on a "
                    "fair price; in return we ask for the longer payment terms below.")
        offer = complete_offer(case, {**terms, **ask, "unit_price": price})

        if status in {"agreed", "final_offer"} or left <= 0:
            if status == "final_offer" and left > 0 and final_ok:
                # their price, our terms: a price-only final sheet leaves other terms at their (costlier) standard
                at_their_price = complete_offer(case, {**terms, **ask, "unit_price": theirs})
                if cost(sid, at_their_price) < cost(sid, terms) and must_haves_ok(case, at_their_price, std[sid]):
                    return _message(case, sid, at_their_price, "We accept your price; please confirm the terms below.")
            if final_ok and status == "agreed":
                return accept | {"message": {**accept["message"], "body": "Thank you, we accept."}}
            return accept if final_ok else {"supplier_id": sid, "message": WALK}
        if beats and sent >= self.min_rounds and cost(sid, terms) <= cost(sid, offer):
            return accept
        st.update(step=step if step is not None else st["step"], price=price)
        return _message(case, sid, offer, body)

from arena_kit.agents.anchor import AnchorAgent
from arena_kit.cost import total_cost

from test_kit import CASE


def _threads(prices, status="open", sent=()):
    ev = []
    for i, p in enumerate(prices):
        ev.append({"from": "sup:A", "status": status if i == len(prices) - 1 else "open",
                   "term_sheets": [{"term_sheet_id": f"o{i}", "terms": {"unit_price": p, "payment_days": 30}}]})
        if i < len(sent):
            ev.append({"from": "buyer", "term_sheets": [{"terms": {"unit_price": sent[i]}}]})
    return {"sup:A": ev}


def _alt(price):
    return {**CASE, "buyer": {**CASE["buyer"], "alternative": {"kind": "x", "ref": None, "terms": {"unit_price": price, "payment_days": 60}}}}


def _price(msg):
    return msg["term_sheets"][0]["terms"]["unit_price"]


def test_opens_twelve_percent_below_non_round_with_rationale():
    msg = AnchorAgent().decide(CASE, _threads([44.0]))["message"]
    p = _price(msg)
    assert 44.0 * 0.87 < p <= 44.0 * 0.88 and round(p * 100) % 50 != 0
    assert "cost review" in msg["body"] and "alternative" not in msg["body"].lower()


def test_concession_steps_shrink_and_are_framed_with_an_ask():
    agent, sent, prices = AnchorAgent(), [], []
    for _ in range(3):
        msg = agent.decide(CASE, _threads([44.0] * (len(sent) + 1), sent=sent))["message"]
        sent.append(_price(msg)), prices.append(_price(msg))
    steps = [b - a for a, b in zip(prices, prices[1:])]
    assert 0 < steps[1] < steps[0]
    assert "significant move" in msg["body"] and msg["term_sheets"][0]["terms"]["payment_days"] == 90


def test_never_accepts_worse_than_reservation():
    case = _alt(36.0)
    assert total_cost(case, {"unit_price": 40.0, "payment_days": 30}) > total_cost(case, case["buyer"]["alternative"]["terms"])
    for status in ("final_offer", "agreed"):
        msg = AnchorAgent().decide(case, _threads([44.0, 40.0], status, [38.0]))["message"]
        assert msg["action"] == {"type": "walk_away"}


def test_accepts_agreed_strictly_better_offer():
    msg = AnchorAgent().decide(_alt(44.0), _threads([44.0, 40.0], "agreed", [38.0]))["message"]
    assert msg["action"] == {"type": "accept", "term_sheet_id": "o1"}


def test_no_live_threads_does_not_crash():
    out = AnchorAgent().decide(CASE, {"sup:A": [{"from": "sup:A", "status": "walked_away", "term_sheets": []}]})
    assert out["message"]["action"] == {"type": "walk_away"}


def test_crash_falls_back_safely(monkeypatch):
    def boom(*a, **k):
        raise RuntimeError("boom")

    monkeypatch.setattr(AnchorAgent, "_decide", boom)
    assert AnchorAgent().decide(_alt(36.0), _threads([44.0, 40.0]))["message"]["action"] == {"type": "walk_away"}


def test_state_resets_for_a_new_case_id():
    agent = AnchorAgent()
    first = _price(agent.decide(CASE, _threads([44.0]))["message"])
    agent.decide(CASE, _threads([44.0, 44.0], sent=[first]))
    again = agent.decide({**CASE, "case_id": "case:T02"}, _threads([44.0], sent=[]))["message"]
    assert _price(again) == first and "cost review" in again["body"]
